// --- PAYOFF MODEL ---

const _payoffModel = function payoffModel(marketSize, adCost, compAdCost, adLift, yourBaseShare, compBaseShare){
  // Computes the payoff matrix for a 2x2 game
  // Actions: 0 = Don't Advertise, 1 = Advertise
  // Shares adjust with ad lift; if both advertise they split the lift

  function computePayoffs(youAd, compAd) {
    let yourShare = yourBaseShare;
    let compShare = compBaseShare;

    if (youAd && compAd) {
      // Both advertise — each gets a partial lift, they split the advantage
      yourShare = Math.min(1, yourBaseShare + adLift * 0.4);
      compShare = Math.min(1, compBaseShare + adLift * 0.4);
    } else if (youAd && !compAd) {
      // Only you advertise — full lift
      yourShare = Math.min(1, yourBaseShare + adLift);
      compShare = Math.max(0, compBaseShare - adLift * 0.3);
    } else if (!youAd && compAd) {
      // Only competitor advertises — they get the lift
      yourShare = Math.max(0, yourBaseShare - adLift * 0.3);
      compShare = Math.min(1, compBaseShare + adLift);
    }
    // else: neither advertises — base shares

    // Normalize shares so they sum to at most 1
    const total = yourShare + compShare;
    if (total > 1) {
      yourShare /= total;
      compShare /= total;
    }

    const yourPayoff = yourShare * marketSize - (youAd ? adCost : 0);
    const compPayoff = compShare * marketSize - (compAd ? compAdCost : 0);

    return { yourPayoff: Math.round(yourPayoff), compPayoff: Math.round(compPayoff) };
  }

  const matrix = [
    [computePayoffs(0, 0), computePayoffs(0, 1)],
    [computePayoffs(1, 0), computePayoffs(1, 1)]
  ];

  return matrix;
};

// --- NASH EQUILIBRIUM FINDER ---

const _nashAnalysis = function nashAnalysis(payoffModel){
  const m = payoffModel;

  // Best response for each player
  // Player 1 (You): rows = your actions, cols = comp actions
  const yourBR_dontAd = m[0][0].yourPayoff >= m[1][0].yourPayoff ? 0 : 1;
  const yourBR_ad = m[0][1].yourPayoff >= m[1][1].yourPayoff ? 0 : 1;

  // Player 2 (Comp): cols = comp actions, rows = your actions
  const compBR_dontAd = m[0][0].compPayoff >= m[0][1].compPayoff ? 0 : 1;
  const compBR_ad = m[1][0].compPayoff >= m[1][1].compPayoff ? 0 : 1;

  // Find pure-strategy Nash equilibria
  const equilibria = [];
  for (let i = 0; i < 2; i++) {
    for (let j = 0; j < 2; j++) {
      const youBestResp = (j === 0) ? yourBR_dontAd : yourBR_ad;
      const compBestResp = (i === 0) ? compBR_dontAd : compBR_ad;
      if (i === youBestResp && j === compBestResp) {
        equilibria.push({
          you: i === 1 ? "Advertise" : "Don't Advertise",
          comp: j === 1 ? "Advertise" : "Don't Advertise",
          yourPayoff: m[i][j].yourPayoff,
          compPayoff: m[i][j].compPayoff
        });
      }
    }
  }

  // Check for dominant strategy
  const yourDomStrategy = (yourBR_dontAd === yourBR_ad) 
    ? (yourBR_dontAd === 1 ? "Advertise" : "Don't Advertise") 
    : null;
  const compDomStrategy = (compBR_dontAd === compBR_ad) 
    ? (compBR_dontAd === 1 ? "Advertise" : "Don't Advertise") 
    : null;

  // Prisoner's dilemma check
  const isPrisonersDilemma = equilibria.length === 1 
    && equilibria[0].you === "Advertise" 
    && m[0][0].yourPayoff > m[1][1].yourPayoff
    && m[0][0].compPayoff > m[1][1].compPayoff;

  return {
    equilibria,
    yourBestResponse: { ifCompDontAd: yourBR_dontAd === 1 ? "Advertise" : "Don't Advertise", ifCompAd: yourBR_ad === 1 ? "Advertise" : "Don't Advertise" },
    compBestResponse: { ifYouDontAd: compBR_dontAd === 1 ? "Advertise" : "Don't Advertise", ifYouAd: compBR_ad === 1 ? "Advertise" : "Don't Advertise" },
    yourDominantStrategy: yourDomStrategy,
    compDominantStrategy: compDomStrategy,
    isPrisonersDilemma
  };
};

// --- DISPLAY ---

const _payoffTable = function payoffTable(payoffModel, nashAnalysis, html){
  const m = payoffModel;
  const ne = nashAnalysis;

  function cell(i, j, player) {
    const val = player === "you" ? m[i][j].yourPayoff : m[i][j].compPayoff;
    const isNash = ne.equilibria.some(e => 
      (e.you === (i===1?"Advertise":"Don't Advertise") && 
       e.comp === (j===1?"Advertise":"Don't Advertise"))
    );
    const bg = isNash ? "background: #2d6a4f; color: white; font-weight: bold;" : "";
    return `<td style="text-align:center; padding:10px; border:1px solid #555; font-size:1.1em; ${bg}">$${val}k</td>`;
  }

  return html`<div style="font-family: system-ui;">
