        <td style="text-align:center; padding:10px; font-weight:bold; border:1px solid #555;">Comp: Advertise</td>
      </tr>
      <tr>
        <td style="padding:10px; font-weight:bold; border:1px solid #555;">You: Don't Ad</td>
        ${cell(0,0,"you")} / ${cell(0,0,"comp")}
        ${cell(0,1,"you")} / ${cell(0,1,"comp")}
      </tr>
      <tr>
        <td style="padding:10px; font-weight:bold; border:1px solid #555;">You: Advertise</td>
        ${cell(1,0,"you")} / ${cell(1,0,"comp")}
        ${cell(1,1,"you")} / ${cell(1,1,"comp")}
      </tr>
    </table>
    <div style="font-size:0.85em; color:#aaa;">Values: Your payoff / Competitor's payoff &nbsp;|&nbsp; <span style="background:#2d6a4f;padding:2px 6px;">Green = Nash Equilibrium</span></div>
  </div>`;
};

const _recommendation = function recommendation(nashAnalysis, adCost, compAdCost, md){
  const ne = nashAnalysis;

  let analysis = "";

  if (ne.isPrisonersDilemma) {
    analysis = `> ⚠️ **Prisoner's Dilemma detected!** Both advertising is a Nash Equilibrium, but you'd *both* be better off if neither advertised. This is a classic trap — without a binding agreement, both players will advertise anyway.

`;
  }

  if (ne.equilibria.length === 0) {
    analysis += `> 🔄 **No pure-strategy Nash Equilibrium.** The optimal strategy depends on unpredictable opponent behavior. Consider a **mixed strategy** — randomize your choice based on expected value.\n\n`;
  } else {
    analysis += `**Nash Equilibria:**\n`;
    ne.equilibria.forEach(e => {
      analysis += `- You: **${e.you}**, Competitor: **${e.comp}** → You earn $${e.yourPayoff}k, Competitor earns $${e.compPayoff}k\n`;
    });
    analysis += "\n";
  }

  if (ne.yourDominantStrategy) {
    analysis += `> ✅ **You have a dominant strategy: ${ne.yourDominantStrategy}.** This is the right choice regardless of what your competitor does.\n\n`;
  }

  analysis += `**Best responses:**\n`;
  analysis += `- If competitor doesn't advertise → You should **${ne.yourBestResponse.ifCompDontAd}**\n`;
  analysis += `- If competitor advertises → You should **${ne.yourBestResponse.ifCompAd}**\n`;

  // Practical recommendation
  const primaryEquilibrium = ne.equilibria[0];
  if (primaryEquilibrium) {
    const shouldAd = primaryEquilibrium.you === "Advertise";
    if (shouldAd) {
      analysis += `\n---\n### 💡 Recommendation: **Advertise**\nAt equilibrium, advertising is the rational choice. Budget: ~$${adCost}k. Watch ROI carefully — if ad effectiveness drops below the tipping point, the calculus flips.`;
    } else {
      analysis += `\n---\n### 💡 Recommendation: **Don't Advertise**\nAt equilibrium, the cost of advertising doesn't justify the payoff. Save your $${adCost}k and invest in product/organic growth instead.`;
    }
  } else {
    analysis += `\n---\n### 💡 Recommendation: **Mixed Strategy**\nNo clear dominant strategy. Consider a probabilistic approach: run intermittent campaigns rather than committing fully.`;
  }

  return md`${analysis}`;
};

const _sensitivityPlot = function sensitivityPlot(Plot, payoffModel, adCost, adLift){
  // Show how your payoff at equilibrium changes with ad effectiveness
  const points = [];
  for (let lift = 0; lift <= 1; lift += 0.05) {
    // Recompute with this lift
    const baseShare = 0.3;
    const compBase = 0.3;
    const mkt = 1000;
    const cost = adCost;

    const noAd = baseShare * mkt;
    const ad = Math.min(1, baseShare + lift) * mkt - cost;
    const bothAd = Math.min(1, baseShare + lift * 0.4) * mkt - cost;

    points.push({ lift, scenario: "Only you advertise", payoff: ad });
    points.push({ lift, scenario: "You don't advertise", payoff: noAd });
    points.push({ lift, scenario: "Both advertise", payoff: bothAd });
  }

  return Plot.plot({
    width: 600,
    height: 300,
    x: { label: "Ad Effectiveness (lift)", domain: [0, 1] },
    y: { label: "Your Payoff ($k)" },
    color: { legend: true },
    marks: [
      Plot.lineY(points.filter(p => p.scenario === "Only you advertise"), { x: "lift", y: "payoff", stroke: "#2d6a4f", strokeWidth: 2 }),
      Plot.lineY(points.filter(p => p.scenario === "You don't advertise"), { x: "lift", y: "payoff", stroke: "#e76f51", strokeWidth: 2 }),
      Plot.lineY(points.filter(p => p.scenario === "Both advertise"), { x: "lift", y: "payoff", stroke: "#264653", strokeWidth: 2, strokeDasharray: "5,5" }),
      Plot.ruleY([0]),
      Plot.ruleX([adLift], { stroke: "#ffd166", strokeWidth: 2, strokeDasharray: "3,3" })
    ]
  });
};

const _sensitivityLabel = function sensitivityLabel(md){return(
