  $def("_viewof_adLift", "viewof adLift", ["Inputs"], _viewof_adLift);
  $def("_adLift", "adLift", ["viewof adLift"], _adLift);
  $def("_viewof_yourBaseShare", "viewof yourBaseShare", ["Inputs"], _viewof_yourBaseShare);
  $def("_yourBaseShare", "yourBaseShare", ["viewof yourBaseShare"], _yourBaseShare);
  $def("_viewof_compBaseShare", "viewof compBaseShare", ["Inputs"], _viewof_compBaseShare);
  $def("_compBaseShare", "compBaseShare", ["viewof compBaseShare"], _compBaseShare);
  $def("_payoffModel", "payoffModel", ["marketSize", "adCost", "compAdCost", "adLift", "yourBaseShare", "compBaseShare"], _payoffModel);
  $def("_nashAnalysis", "nashAnalysis", ["payoffModel"], _nashAnalysis);
